# rung 6. The self-consistent field

# Symmetric orthogonalization: X = S^(-1/2) = U diag(1/sqrt(s)) U^T.
s_vals = zeros(n_basis)
s_vecs = zeros(n_basis, n_basis)
eig_sym(S, s_vals, s_vecs)
D_inv_sqrt = zeros(n_basis, n_basis)
for i to n_basis {
    D_inv_sqrt[i, i] = 1.0 / sqrt(s_vals[i])
}
X = s_vecs @ D_inv_sqrt @ transpose(s_vecs)
ortho = transpose(X) @ S @ X
n_occ = 1
E_nuc = Z[0] * Z[1] / sqrt(dist_sq(center_of(0), center_of(1)))
P = zeros(n_basis, n_basis)
eps_vals = zeros(n_basis)
E_total = 0.0
converged = false
n_iter = 0.0
for iter to 50 {
    # G = sum P [(mu nu | lam sig) - 1/2 (mu lam | nu sig)]
    G = zeros(n_basis, n_basis)
    for mu to n_basis {
        for nu to n_basis {
            g = 0.0
            for lam to n_basis {
                for sig to n_basis {
                    g += P[lam, sig] * (eri[mu, nu, lam, sig] - 0.5 * eri[mu, lam, nu, sig])
                }
            }
            G[mu, nu] = g
        }
    }
    F = H_core + G
    Cp = zeros(n_basis, n_basis)
    eig_sym(transpose(X) @ F @ X, eps_vals, Cp)
    C = X @ Cp
    P_new = zeros(n_basis, n_basis)
    E_elec = 0.0
    for mu to n_basis {
        for nu to n_basis {
            s = 0.0
            for a to n_occ {
                s += C[mu, a] * C[nu, a]
            }
            P_new[mu, nu] = 2.0 * s
        }
    }
    for mu to n_basis {
        for nu to n_basis {
            E_elec += 0.5 * P_new[mu, nu] * (H_core[mu, nu] + F[mu, nu])
        }
    }
    E_total = E_elec + E_nuc
    delta = 0.0
    for mu to n_basis {
        for nu to n_basis {
            delta = max(delta, abs(P_new[mu, nu] - P[mu, nu]))
        }
    }
    P = P_new
    n_iter = iter + 1.0
    if delta < 1.0e-8 {
        converged = true
        break
    }
}
show n_iter
show eps_vals
show E_total
test "X orthonormalizes the basis: X^T S X = 1" {
    assert_near(ortho[0, 0], 1.0, 1.0e-12)
    assert_near(ortho[0, 1], 0.0, 1.0e-12)
}
test "H2/STO-3G: E = -1.1167 hartree at R = 1.4 bohr (Szabo and Ostlund)" {
    assert_true(converged)
    assert_near(E_total, -1.1167, 5.0e-5)
}
